) AS (
  VALUES 
    (497::BIGINT, 'Es muy buena nota, se nota que le gusta dar clases. Al explicar a veces se le entiende y a veces no. Los quices y tareas que deja no son difíciles, pero puede que falte preparación para los examenes de catedra. Si se lleva en Verano o RN no es tan difícil pasar, si se lleva normal preparese.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases largas']::TEXT[], '2026-11-02T00:00:00+00:00'::TIMESTAMPTZ, '5947b20ce2eb1aab7d28eda5bca4236e1edf7d217b8249e18e2557e61d571304'::TEXT, ARRAY[634]::BIGINT[]),
    (497::BIGINT, 'Muy bueno a mi parecer, sí hay que estudiar por aparte pero el ayuda mucho y califica muy suave. Tiene métodos para entender la materia de forma mucho más sencilla.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-12T00:00:00+00:00'::TIMESTAMPTZ, '7d962c4dcdd3ba37398ab03ca38380300d44c738197d8461af2acd6aef2be405'::TEXT, ARRAY[605]::BIGINT[]),
    (497::BIGINT, 'Muy difícil, no se le entiende, es muy disperso al explicar y a veces se confunde todo, además a las chicas las ve de forma extraña'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2026-01-19T00:00:00+00:00'::TIMESTAMPTZ, '387d646804fdbb0eaa99702092c711bdc649a9d9b0e68d2f401f10b3b6afb6f2'::TEXT, ARRAY[605, 923, 2444]::BIGINT[]),
    (497::BIGINT, 'Malparido bigotón, tiene más ganas de salir a echarse unas frías que de explicar, la última vez que hizo algo bien fue cuando no fue a dar clases porque es una pérdida de tiempo total, en general si puede matricular con él, no lo haga'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-10-15T00:00:00+00:00'::TIMESTAMPTZ, 'b6a726b61d97b7a2eb189b4773b98da9ea3207ee780ae6423b24a84ba846b057'::TEXT, ARRAY[563]::BIGINT[]),
    (497::BIGINT, 'No explica bien, parece que ni entiende de la materia. Hace que ir a sus lecciones sea una pérdida total de tiempo. Revisa las tareas cuando le da la gana, incluso si puso una fecha de revisión. Si llevan con él estudien con la cátedra, por qué solo enseña la mitad del examen.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-03T00:00:00+00:00'::TIMESTAMPTZ, '7458b3a98024ee79d480832cc6339c61ab75fd5508517cd84fbc7b4e42cc8b25'::TEXT, ARRAY[605, 923, 2444]::BIGINT[]),
    (497::BIGINT, 'un acosador que trata de aprovecharse de las muchachas. Mujeres tengan cuidado de nunca quedarse a solas con el. Mandaba mensajes inapropiados a las chicas de la clase en las madrugadas'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-04-25T00:00:00+00:00'::TIMESTAMPTZ, '645b28aa7259ca35ed616af9265f113fe10d2ce52f8abed594a1e1aeb7e320b4'::TEXT, ARRAY[634]::BIGINT[]),
    (497::BIGINT, 'El peor profesor que hay en todo el TEC, no se le entiende absolutamente nada, si le preguntas por algun paso no sabe responderte. Si sales del aula se enoja, dejando quicez de asistencia para hacerte perder puntos. Coqueetea con las estudiantes Reitero, peor profe del TEC, no matriculen con él.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2025-04-14T00:00:00+00:00'::TIMESTAMPTZ, 'b1fda1a101c73126734fd584fe5377aa375084fd5c70fbee5ebd06eec53ac19b'::TEXT, ARRAY[634]::BIGINT[]),
    (497::BIGINT, 'Muy buen profesor, bastante cómico y ayuda bastante si uno lo ocupa'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-10-17T00:00:00+00:00'::TIMESTAMPTZ, '04cd22e5fc28f416549816d1fa9f5a6dcdcf2e7bc80cd05f0b62b8fe73bf54b8'::TEXT, ARRAY[563]::BIGINT[]),
    (497::BIGINT, 'El profe no es claro con la materia de discreta y tiende a saltarse pasos, por ende no explica bien, necesario repasar TODOS los videos y temas de discreta en la cátedra para pasar con el profe. Califica duro, sin embargo, las tareas y quices son sumamente sencillos 30% ganado. Profe regular.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'd183cea0d65b7f8d7a371c3b5e687dc3afd6053afff1d86de96bc973a75be290'::TEXT, ARRAY[1018]::BIGINT[]),
    (497::BIGINT, 'El peor error que cometí en mi vida del TEC hasta ahora fue matrícular con dicho profesor, sí lo pueden evitar a toda costa no lleven absolutamente nada con él y sí no le queda ninguna opción mejor ni matrículen la materia, tarda en responder y no da retroalimentación aún llendo a repo.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '62b6fa739d67a092f09e2a49598b887ebcaceb194f299e2fa166e0bb328487ca'::TEXT, ARRAY[1018]::BIGINT[]),
    (497::BIGINT, 'de 37 que metimos discreta pasamos como 8, las clases de este mae no sirven porque hay que ser muy autodidacto con el, da ejemplos de 1+1 pero en el examen salen raices ( veanlo asi ), es alcahueta un toque pero todos se quedan/abandonan, ademas es un viejo verde'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2024-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'e69156509686d392aef6a15033b633964a889cc4ed58281b81433eeb53ca2a7e'::TEXT, ARRAY[1018]::BIGINT[]),
    (497::BIGINT, 'El profesor de matemáticas no explica bien y sus clases son confusas. No lo recomiendo, ya que muchos estudiantes no entienden y quedan rezagados. es una porqueria del tec, lo mejor que puede hacer es pensionarce'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2024-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'eb1d7420a17c4b4a9790d66b519b9eb84efd8e63027a285f5e4bb366a9c1da13'::TEXT, ARRAY[563]::BIGINT[]),
    (497::BIGINT, 'El profe se ve que es pura vida, aveces da puntos en los examenes si reclamas, sin embargo no se le entiende en las explicaciones, suele confundirse, enredarse y perderse al resolver ejercicios. Deja tareas, pero no da retroalimentacion, nada mas procura que esté hecha, no que esté buena.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2024-06-14T00:00:00+00:00'::TIMESTAMPTZ, '432aa63b8012b0d707289bd16ea79e4cd7143814ad615c687aaabb3d91eb1e1c'::TEXT, ARRAY[1018]::BIGINT[]),
    (497::BIGINT, 'Este mae no sabe lo que esta haciendo, NUNCA lleven discreta por primera vez con el. Siempre explica muy por encima y a veces hasta con varas que no van en el examen.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2024-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'eb7ff25e446ae284f26c83a4865bb9d0a04f84f5cffcc4102cba2e685877ac09'::TEXT, ARRAY[1018]::BIGINT[]),
    (497::BIGINT, 'Mal profesor. Además, le tiraba comentarios bastante pasados y con doble sentido a compañeras.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-10T00:00:00+00:00'::TIMESTAMPTZ, '943826a301a7a5dccbb1b6f4755a0fc2c59553e1ef9173878b34e204ae1fd44b'::TEXT, ARRAY[634]::BIGINT[]),
    (497::BIGINT, 'Básicamente si quiere pasar estudie con la cátedra (aunque también es un desastre). El profe se enreda con los ejercicios y casi nunca llega a la solución correcta. Si tiene la posibilidad de matricular con otro profe, no lo dude.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-12-18T00:00:00+00:00'::TIMESTAMPTZ, '13bb66b5e0aff15e48696cac772e222f31f3cb8a777200415d428b2ab66c281d'::TEXT, ARRAY[1049]::BIGINT[]),
    (497::BIGINT, 'Mal profesor, explica malísimo, se distrae a contar cosas de su vida que son bastante deprimentes y se nota que no tiene el mínimo interés ni por los estudiantes ni por el curso, simplemente llega a escupir materia y listo. Es increíblemente malo explicando y nada de lo evaluado lo aprendí con el.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-12-05T00:00:00+00:00'::TIMESTAMPTZ, 'dfb430795391815d013bb60f34a2fff5329a0ff7faef1bec966278d721195f46'::TEXT, ARRAY[563]::BIGINT[]),
    (497::BIGINT, 'Mmm el mae aveces se enreda, pero la materia del curso es muy Easy. Tiene tips que funcionan. Mmm el mae deja como un cuaderno de tareas lo bueno es que son ejercicios que sirven para repasar. El mae aveces hacer comentarios que nada que ver, pero no era tan malo cómo lo pintaban'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-01T00:00:00+00:00'::TIMESTAMPTZ, '2b2ddfdbc5eaaa42ec9e4303ee93f6f6f9fea5a3c2c4129b1ec2d56e9e4d1572'::TEXT, ARRAY[935]::BIGINT[]),
    (497::BIGINT, 'Es un pesimo profesor, no explica nada bien los ejercicios. Cuando esta explicando se enreda solo y usualmente los resuelve mal. bajo ninguna circunstancia matricule con el, no pierda su tiempo.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-19T00:00:00+00:00'::TIMESTAMPTZ, '6cd909772ce374d7cf26e997764d2fdc5959bd4bb7bb958bbd3cc6e967cbd430'::TEXT, ARRAY[1049]::BIGINT[]),
    (497::BIGINT, 'Yo no le entendía nada las clases eran largas y él hace chistes un poco machistas, lo bueno es que el porcentaje que no es de examenes se gana fácil porque el califica muy suave. Si matricula con él mejor estudie de la cátedra.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'e0e8c2b55b722971c6fa92bc568ee9e44a2701b8493ddb1fda30c191af5c3ba3'::TEXT, ARRAY[1018]::BIGINT[]),
    (497::BIGINT, 'Pésimo profesor. Las clases son una pérdida de tiempo, con que usted haga las guías de cátedra le va bien. El problema es que el profe tiene un 20% de su nota entonces toca ir a perder el tiempo y aguantarse los comentarios sin gracia que hace. Al final igual le baja puntos a uno sin justificación.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'dfe63b23e18a9ecf98de06aca762a35b1b9e90b3e1e1f878556b45d851855bc1'::TEXT, ARRAY[1057]::BIGINT[]),
    (497::BIGINT, 'NUNCA matriculen con él. No se le entiende ninguna explicación, parece que siempre tiene pereza para dar clases. El reclamarle puntos es una cosa super tediosa también. Definitivamente no matricule con él, sino van a necesitar mucha ayuda fuera de clases'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '4929a7ffe2102e4453a0261037954f54b10eba64511e2242f75ca90ab2e94f5e'::TEXT, ARRAY[1018]::BIGINT[]),
    (497::BIGINT, 'Continuación. En el tema de retroalimentación, no justifica porque baja puntos y el reclamarle es tedioso porque se abstiene a corregir. Las clases no son obligatorias en sí pero si usted falta, él lo recordará y créeme no quieres eso. En resumen: Inmadura y cero profesional. No recomendado'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Asistencia obligatoria']::TEXT[], '2023-06-17T00:00:00+00:00'::TIMESTAMPTZ, '3a17660daec54f02203d6285399ec165db969cb9b30d147b1136c90a41716672'::TEXT, ARRAY[1057]::BIGINT[]),
    (497::BIGINT, 'Conforme transcurre cada semana, la actitud del profe se vuelve más nefasta, empieza a tomarse cada situación como un ataque personal, al punto que en muchas clases el profe toma como tema principal el resentimiento. Esto inclusive afecta las notas porque las califica de manera subjetiva. Continuará'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Asistencia obligatoria']::TEXT[], '2023-06-17T00:00:00+00:00'::TIMESTAMPTZ, '11fe010f990175762519ffda9017ff71281b612105e8697917f946efed041927'::TEXT, ARRAY[1057]::BIGINT[]),
    (497::BIGINT, 'No es la mejor opción'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-05-30T00:00:00+00:00'::TIMESTAMPTZ, '246ad3774d6d05853ca006b1872e1162bdc68d03804f41c4c4ca78927da9f329'::TEXT, ARRAY[1057]::BIGINT[]),
    (497::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2023-02-28T00:00:00+00:00'::TIMESTAMPTZ, '5f67008f5b06746bddb942a4554975f9ec093f1a1031bbfd207ed18cc847f7be'::TEXT, ARRAY[563]::BIGINT[]),
    (497::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-08T00:00:00+00:00'::TIMESTAMPTZ, '731f2c1d0cd37a1c8a552da9c0f27c2b1f021af2f11186daa8a99b1770d9429b'::TEXT, ARRAY[1049]::BIGINT[]),
    (497::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-23T00:00:00+00:00'::TIMESTAMPTZ, '3f72033d329bfba438f757fa997b6fe7b620abf6746007eb389a94b68238b48f'::TEXT, ARRAY[634]::BIGINT[]),
    (497::BIGINT, 'Sinceramente, no lo haga compa Completamente desordenado al momento de calificar proyectos/tareas dice una cosa pero hace otra?????, las calificaciones las deja para el puro final, hay situaciones en las que se tiene un ambiente de acoso con ciertas compañeras'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-15T00:00:00+00:00'::TIMESTAMPTZ, '67d56ba7095d1847b9e891933d1dbce0c37575fd544b020a23ed1b05746843d1'::TEXT, ARRAY[605, 923, 2444]::BIGINT[]),
    (497::BIGINT, 'NO se le ocurra llevar cualquier mate con este profe.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-02T00:00:00+00:00'::TIMESTAMPTZ, '92847acd265e0716b2026270e38e80d2cb16831af16129fcb375f961e8b65cfc'::TEXT, ARRAY[1049]::BIGINT[]),
    (497::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2022-02-25T00:00:00+00:00'::TIMESTAMPTZ, '33f632a8882b78f0a7ffb5f2c625cf63d2a48c353fdaa74dcd156638d537a2a8'::TEXT, ARRAY[1018]::BIGINT[]),
    (497::BIGINT, 'Es el peor profe que he tenido. Explica muy por encima, da las calificaciones al puro final del curso, el ambiente es un poco incómodo ya que se nota que es un acosador. A menos que esté repitiendo el curso (y ni así), evítelo a toda costa.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2022-01-15T00:00:00+00:00'::TIMESTAMPTZ, 'f9a371b4844e53c8c01d2c09f3bce58625798b1e2e10567b3f065755846ea9ac'::TEXT, ARRAY[605]::BIGINT[]),
    (497::BIGINT, 'Muy mal profesor, no se le entiende lo que explica, de verdad nunca lleve un curso con él aparte que es un desordenado'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, '2c7c3ec6748845b08ee4b880318f67131df8c169b2eb8b0eafa97b73de996b0b'::TEXT, ARRAY[1018]::BIGINT[]),
    (497::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, '2b7e843f579fedbb844fdbe82a4face05aefaa81ed81f6c77f332a2af076f128'::TEXT, ARRAY[563]::BIGINT[]),
    (497::BIGINT, 'EVÍTELO. Sus clases son ver los videos de Khan Academy, explica luego (porque NOSOTROS los estudiantes le pedimos que explicara él) y manda el pdf, hace muchos ejemplos pero no es claro, esconde las calificaciones hasta el final de semestre y si vos hacés preguntas las evita y te ignora. Todo mal'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2021-07-12T00:00:00+00:00'::TIMESTAMPTZ, '2ab09919da75d907804c21fc31b197566452762a20c8856fa29e20d6eb48e2aa'::TEXT, ARRAY[563]::BIGINT[]),
    (497::BIGINT, 'Evitar a toda costa este profesor, las clases son solamente de ver videos de Khan Academy y si se le pregunta sobre algo más no lo contesta, machista, atrasa los temas demasiado y no se aprende absolutamente nada con él, no lo lleve.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'de0dea0685772d17be14e1ef08483dccdc9a0750f5c9b3220f138adfee6b8150'::TEXT, ARRAY[563]::BIGINT[]),
    (497::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2021-05-25T00:00:00+00:00'::TIMESTAMPTZ, 'ab4e06ff4d6c6df9c320e5afd7a81eab82d4b7a463a65d7ae8fb0c6ad43021cb'::TEXT, ARRAY[563]::BIGINT[]),
    (497::BIGINT, 'Llevo 3 semanas de llevar clases con este profe y sólo pone videos de Khan Academy, no explica nada y cuando lo hace es un caos. Cuando le preguntan algo sobre un tema específico, lo evade.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2021-03-04T00:00:00+00:00'::TIMESTAMPTZ, '43ce823851d01a62aeb149d819db4ba1d88b6a28a03453be48b2f23e5cd01a9e'::TEXT, ARRAY[563]::BIGINT[]),
    (497::BIGINT, 'Machista y acosador con las mujeres, pésimo profe. No revisa bien y trabajos no relacionados con el curso'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '62da3c87943b65936abdde028f0df0cbd51dae131db8a53440e1764f8b5d65bd'::TEXT, ARRAY[634]::BIGINT[]),
    (497::BIGINT, 'Si puede evitarlo mejor, si es para repetir el curso no hay problema ya que con lo que explica no se aprende pero ni para poder hacer las tareas'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, '74bf162b8197649d2bbeb2fc5a56a546820a7e797d5b72e6b49825e9f674efca'::TEXT, ARRAY[634]::BIGINT[]),
    (497::BIGINT, 'Simplemente no, las clases son aburridas, deja trabajos que no tienen que ver con la materia, solo porque le da la gana, no respeta las fechas de vacaciones. No se aprende nada'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, '694a33a0d01edaef0cb9b1d613b6ef20f25c40a158b9846e4812c6aabfa1b58a'::TEXT, ARRAY[634]::BIGINT[]),
    (497::BIGINT, 'Un profesor muy malo en enseñar'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2021-01-21T00:00:00+00:00'::TIMESTAMPTZ, '6814c8a03027a66013358a0fc0fce38e86169b04ed4e0e06dfad331ad2c8ff38'::TEXT, ARRAY[1018]::BIGINT[]),
    (497::BIGINT, 'sabe mucho pero es un PÉSIMO profesor. Las clases son muy monótonas y no sabe explicar. Aún así intenta vagamente que todos entiendan, sin embargo no lo recomiendo'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-12-21T00:00:00+00:00'::TIMESTAMPTZ, 'bad76bdd94ae16b5c98fcd18a937d99a98bb975402663509870ceef2ac8c2dac'::TEXT, ARRAY[634]::BIGINT[]),
    (497::BIGINT, 'Es el tipo de profe que tiene que cuidar examen y se duerme 20 minutos (literalmente lo hizo ) deja tareas faciles pero no explica nada bien'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra']::TEXT[], '2020-08-31T00:00:00+00:00'::TIMESTAMPTZ, '598d0fbe5de5ac61364aa508e1d8a4d0812334a9b25ff0de9bb7b8746ab6e2e9'::TEXT, ARRAY[605]::BIGINT[]),
    (497::BIGINT, 'No explica para nada bien. Se nota que sabe del tema, pero es deficiente para enseñarlo. Matriculé con él y tuve que asistir a clases con otro profesor para entender la materia. No lo recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Pocos exámenes']::TEXT[], '2020-08-27T00:00:00+00:00'::TIMESTAMPTZ, 'b8460c8c4f89655324193c219712707fb80bf9bc9f66120a916da8b1a2f0dd08'::TEXT, ARRAY[634]::BIGINT[]),
    (497::BIGINT, 'Comentarios y "chistes" machistas, miradas acosadoras a las mujeres, es tan vago que le enseña atajos para hacer las cosas más fáciles. Recomiendo que no matricule con él si va a llevar la materia por primera vez'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2020-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'acae07cc3ab292615a1dc49c94f4609a3a47f12d56e9bb67cbf500257fbceb15'::TEXT, ARRAY[634]::BIGINT[]),
    (497::BIGINT, 'Llega tarde y a veces oliendo a alcohol, explica mal y exhibe conductas muy acosadoras, en mi grupo siempre acosaba a la muchacha a la que mejor le iba. a fin de cuentas es muy fácil, pero jamás matricule con él a menos de que sea la última opción.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-24T00:00:00+00:00'::TIMESTAMPTZ, '3952aa91bc86d0b461f2501b6614f6aa6e37d12ab6f2812dde13d35ef5df48d7'::TEXT, ARRAY[634]::BIGINT[]),
    (497::BIGINT, 'La verdad si se asiste a todas las clases el mae es muy pura vida y lo ayuda con bretes extra'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2019-11-20T00:00:00+00:00'::TIMESTAMPTZ, '4363e76d4377f8238cd54093f419ae43c03783c1546fde2acc45a5918c5e0e71'::TEXT, ARRAY[605]::BIGINT[]),
    (497::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-09-14T00:00:00+00:00'::TIMESTAMPTZ, '72d647126322bd1d3cfb16b639da53a41b77815d7fc3534c92265fd2ba9c94f4'::TEXT, ARRAY[634]::BIGINT[]),
    (497::BIGINT, 'El peor profesor que me ha tocado en la carrera. Hace chistes machistas y es un acosador. SI ES MUJER NO MATRICULE CON EL. Con respecto a la materia, no sabe explicar y no se le entiende nada'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2019-08-27T00:00:00+00:00'::TIMESTAMPTZ, '93cedefdab6febf394a534d40eb06392780b2e746f40aa11382683556df5b40e'::TEXT, ARRAY[605]::BIGINT[]),
    (497::BIGINT, 'Trata de ser cómico, más sin embargo no sabe explicar bien, da ejemplos muy simples. hace prácticas y hace que los estudiantes pasen al frente a resolverlos, o si no pierdes puntos. Hace bromas muy pasadas a veces. Es buena gente pero no es para enseñar'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('25','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-28T00:00:00+00:00'::TIMESTAMPTZ, '840890ce5ab62ca7d1ed73f09aa097f48b3eb938754d2c19e01e6192925ba810'::TEXT, ARRAY[605]::BIGINT[]),
    (497::BIGINT, 'Lo evalué hace como cuatro años, pero sigo seguro de que este mae no ha cambiado. Es una VERGA de profesor.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '1356219adfc18a1c3dcc3c1d0ac1a6f44916511e5b238e9c0daa5628a95ff9a9'::TEXT, ARRAY[605]::BIGINT[]),
    (497::BIGINT, 'Es buena gente, pero solo lo recomiendo para personas que deban llevar por segunda vez el curso. Aprendí varios trucos para resolver ejercicios!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2018-12-01T00:00:00+00:00'::TIMESTAMPTZ, '20cf97cfacbb8ec94f7560ff8499e89d465710f1c37c5741c77b2da49ecd68f7'::TEXT, ARRAY[563]::BIGINT[]),
    (497::BIGINT, 'El peor profesor que me he topado.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-21T00:00:00+00:00'::TIMESTAMPTZ, '4db03ab3339321253582aa9662253c7ec5f4a2985f5296b6d90182b2f3f7d25d'::TEXT, ARRAY[605, 923, 2444]::BIGINT[]),
    (497::BIGINT, 'Es vergonzoso que esta persona sea profesor del TEC, sin duda el peor profesor que tuve en la carrera. Llega tarde, el mae promueve que el aula sea un puro chingue, explica super mal. Al final, le da puntos a todo el mundo para que nadie se quede. Ojala algún día no queden profesores así en el país.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'd9a565e0e3a10fe50a68e001bcc49ddda6c7fbf3cc39b4433e9cec146b267725'::TEXT, ARRAY[563]::BIGINT[]),
    (497::BIGINT, 'Siempre llega tarde a clase, la materia que da no tiene la misma dificultad que la de los exámenes, se salta algunos temas, o no los ve como debería. Aunque a veces da trucos útiles o más sencillos.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'c389f68af006d6fbfc80a2f1e26fbabfe11ff49c727fd64f1081eb10b414c22b'::TEXT, ARRAY[563]::BIGINT[]),
    (497::BIGINT, 'Es un pesimo profesor ni el entiende la materia todo es supongamos por aqui y supongamos por aya.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-05T00:00:00+00:00'::TIMESTAMPTZ, '10afd327bc4ec78f912f3490bdfbcf6bc3e05f32d752c42a79f106f17b0270be'::TEXT, ARRAY[1018]::BIGINT[]),
    (497::BIGINT, 'Llega tarde siempre, no da una buena preparación para los exámenes, siempre se enreda solo y no sabe resolver los ejercicios y hace bromas inapropiadas.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-05T00:00:00+00:00'::TIMESTAMPTZ, 'f8f871ede6e2431986c65732a39980949df82b562b5df2a461ae2e44e1f41cf8'::TEXT, ARRAY[1018]::BIGINT[]),
    (497::BIGINT, 'Siempre llega tarde y no enseña matemáticas, solo trucos y a usar calculadora'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'fd66ee52e614dd6a486c90ce2e754e0616572993cd6eb43829dbbd4dec28f0ae'::TEXT, ARRAY[563]::BIGINT[]),
    (497::BIGINT, 'Es un profesor muy desordenado, llega siempre tarde a clases, su plan de evaluación lo cambia todos los días dependiendo del humor que ande. Habla por teléfono toda la clase, da ejemplos desastrosos y no prepara absolutamente nada bien para examen. Si está con el prepárese para buscar tutorías'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-04-19T00:00:00+00:00'::TIMESTAMPTZ, '63f592bb3622099fc55b491697092ff3d26a1d5b3f15564b22b20c1eb13a6fc2'::TEXT, ARRAY[563]::BIGINT[]),
    (497::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2018-03-13T00:00:00+00:00'::TIMESTAMPTZ, 'a937ffc271934b5e4b0708a09ef4e71c2ac3325819f70164fe5ea35f73b6829e'::TEXT, ARRAY[563]::BIGINT[]),
    (497::BIGINT, 'Pesimo la verdad, no le entiendo ni Hostia, se enreda solo y no abarca bien los temas'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-02-17T00:00:00+00:00'::TIMESTAMPTZ, '52fd74a587bd35136cf544679576bf28c301485622dfa915508a849c6d91589e'::TEXT, ARRAY[563]::BIGINT[]),
    (497::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-30T00:00:00+00:00'::TIMESTAMPTZ, '2b45a78a9ee7f3ea22e4a8a72b35186505dc4f40c4c8f938bec2ec5d4310dd62'::TEXT, ARRAY[563]::BIGINT[]),
    (497::BIGINT, 'EL PEOR PROFE! Siempre pasa con el teléfono, solo se pasa durmiendo en la clase, entre menos tenga que hacer mejor para él, expone ejemplos que ni él sabe como resolver!NO MATRICULE CON ÉL!'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-21T00:00:00+00:00'::TIMESTAMPTZ, '894a721ed14f91b315bbeb0f918b4393d261b177dead3e28e6c122e53a581852'::TEXT, ARRAY[605]::BIGINT[]),
    (497::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, '641e16ab98abf52db18927f0b258e35473494e4642c115df8f3daa20979cfac7'::TEXT, ARRAY[634]::BIGINT[]),
    (497::BIGINT, 'Para los que repiten el curso otra vez se lo recomiendo, pero para pasar lo llevé con RAMA y me la jugué solo porque ese profe a veces salta temas y además llega tarde. El pone quices fáciles y califica suave. Si es la primera vez que lleve la materia mejor no porque vas a lactar en los exámenes.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2017-11-27T00:00:00+00:00'::TIMESTAMPTZ, '19c19fd9dce9c5c5c668333cd70772b93918144c4ef3895b514046f68ed86200'::TEXT, ARRAY[563]::BIGINT[]),
    (497::BIGINT, 'NUNCA METAN UN CURSO CON ÉL'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'bf7c07f1dfc69ceedbac01894fa4d446b735eac83949f42d3c3dd7a2b047116a'::TEXT, ARRAY[605]::BIGINT[]),
    (497::BIGINT, 'NUNCA MATRICULE CON ÉL'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '0c9569f143df5d34b3701e83165dded743cf82c0a7eb9e0cab5ab92609268031'::TEXT, ARRAY[605]::BIGINT[]),
    (497::BIGINT, 'Los métodos que utiliza para explicar son absurdos. Durante las lecciones solo se ven la cuarta parte de los temas que entran en los exámenes. Pésimo profesor.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'a84bbf79992787a383db94fc0aaadb22e2598f8cceae0b8b9389e3b848215cab'::TEXT, ARRAY[563]::BIGINT[]),
    (497::BIGINT, 'Explica buenos métodos para hacer las cosas más fáciles pero no da buenas bases como para llevar el curso por primera vez. Revisa no muy fuerte, llega tarde, chistes inapropiados...'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, '53dc07516ef68f3aab18f02951cde8e61278c264b8ebcc61900ef9701d6bbb18'::TEXT, ARRAY[605]::BIGINT[]),
    (497::BIGINT, 'Es un buen profe, pero no es recomendable llevar con él si es la primera vez que se lleva el curso, pues enseña métodos para resolver los ejercicios. 100% recomendado si tiene que repetir el curso.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, '85785361e66a0aedfe5a6cea19987d0332ac98869d658e38db1fc0c81457e14d'::TEXT, ARRAY[605]::BIGINT[]),
    (497::BIGINT, 'NUNCA MATRICULE CON MANUEL CALDERÓN. Se enreda solo, no explica bien, cuenta chistes malos, no sabe resolver los propios ejercicios que pone, va a ir muy mal preparado para los exámenes y los siguientes cursos'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'fc101047018c55f1e5c43156ba4c8d7ce542a8537232280c105e05040e171ae2'::TEXT, ARRAY[605]::BIGINT[]),
    (497::BIGINT, 'Pésimo profesor, paupérrimos métodos didácticos, su calidad es irrisoria. Tiene cero interés en el curso y en que sus estudiantes aprendan. Muy desordenado, siempre llega tarde. No se lo recomiendo a nadie.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes']::TEXT[], '2017-05-09T00:00:00+00:00'::TIMESTAMPTZ, '0363621fe243b1aab26024e923b84cb5f09b8bdbf4e681685d1cf08391cbe3fd'::TEXT, ARRAY[605]::BIGINT[]),
    (497::BIGINT, 'Se enreda mucho explicando por lo que uno tiene que ser autodidacta, a veces sale con cosas que no son pertinentes del curso, llega tarde y dura mucho en entregar los parciales, los quizes con fáciles.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-19T00:00:00+00:00'::TIMESTAMPTZ, '602148f5fc590034b4b007f4c30c67302594589a8bacf857f53ce66d2362f69e'::TEXT, ARRAY[935]::BIGINT[]),
    (497::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'e66d0d3af49ca45eeac378df1b49cb734c4a16aa1cbc8c8ecf3fbe76f5ffc267'::TEXT, ARRAY[605]::BIGINT[]),
    (497::BIGINT, 'Es un buen profe, generalmente ayuda cuando lo pides, y los quizes son de asistencia. Lo recomiendo solo si ya se sabe del tema o se esta repitiendo el curso. El sabe bastante, no lo desaprovechen.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-05-03T00:00:00+00:00'::TIMESTAMPTZ, 'cd80a9090ed7c3583fad897697ba6af393532c1bc2afcc375d62956987ba93f0'::TEXT, ARRAY[605]::BIGINT[]),
    (497::BIGINT, 'Si estas leyendo esto por favor no cometas el error de matricular una mate con Manuel. Aunque pasé el curso la verdad no aprendí lo debido porque este profe da lo básico y califica muy suave. Desorganizado con las evaluaciones y el concepto de quices los vale por asistencia a clases.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-27T00:00:00+00:00'::TIMESTAMPTZ, '49df42e78d7d520211534db1aeb352ae106b34336e3f2915e4c743423dde499d'::TEXT, ARRAY[605]::BIGINT[]),
    (497::BIGINT, 'El curso es fácil, y por más que usted se quede el profe lo manda a repo. Si quiere apreder no meta con este profesor. Es de lo peor. Y si lo hace y quiere aprender, recomiendo llevar rama.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-21T00:00:00+00:00'::TIMESTAMPTZ, '7991ac3a1999d4809aa9f2d8cf6413e286bf19a7a6925f36db6d420b63d5261f'::TEXT, ARRAY[563]::BIGINT[]),
    (497::BIGINT, 'Por motivos personales no logre hacer el I examen asi que hice el extraordinario.... Aun sigo esperando la nota de ese examen.... PD: Eso fue el semestre pasado.... Y aun no se cuanto me saque....'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-03T00:00:00+00:00'::TIMESTAMPTZ, '77d6641bc6399b352250c850fef98fb023ec3461f5a0d3fabed46c1a119e8be8'::TEXT, ARRAY[563]::BIGINT[]),
    (497::BIGINT, 'Da metodos alternativos y muy divertidos. sin decir que es muy gracioso. aunque aveces le falta para personas que les cuesta mucho aprender o que traen malas bases'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, '5bb074ec4dcc25250be97d0c3724341a0affb74e4d04c6131ef82505ba300e8f'::TEXT, ARRAY[563]::BIGINT[]),
    (497::BIGINT, 'Yo lo recomiendo para cursos que uno esté repitiendo, facilita mucho las cosas.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'c08827acb7856885ec8e4a8bb6af23a6797e942bb54d0a2f8302f93b91a0ffca'::TEXT, ARRAY[563]::BIGINT[]),
    (497::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-02T00:00:00+00:00'::TIMESTAMPTZ, '8ecd3d2957768b617df41c5fa8e767dce492a92ce87f28d79bbe522c562ae81d'::TEXT, ARRAY[563]::BIGINT[]),
    (497::BIGINT, 'si quiere pasar adelante, pero va a lactar el siguiente curso'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-02-03T00:00:00+00:00'::TIMESTAMPTZ, '219ec8ed2b1548e5f9ecc0135f541385d5e11931f7c4808016f4328cce2ca6da'::TEXT, ARRAY[605, 923, 2444]::BIGINT[]),
    (497::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('15','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-27T00:00:00+00:00'::TIMESTAMPTZ, '20a6eb8a2b83cd9b357ef8ecbf7716d1051fafd2fc42b032754fee4dbaf4ff52'::TEXT, ARRAY[605, 923, 2444]::BIGINT[]),
    (497::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'fe4661036c8845813af91abcb141a73d71fa1bd911ee4182bf55cf02f392cc3b'::TEXT, ARRAY[605]::BIGINT[]),
    (497::BIGINT, 'No es el mejor pero practicamente regala los quices y explica lo suficiente como para enterder el tema'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '40be5e6e5f98b0c0389d83e03a480e1188155590fab6cb7772f1e02139251bc0'::TEXT, ARRAY[605]::BIGINT[]),
    (497::BIGINT, 'Pesimo profesor, solo para verano si no quiere aprender nada, solo sabe dar chistes y no sabe trabajar en consulta.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('15','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'c353a4631d6c9af7e1485babf3f812c22833e6d213a69195a82a9fe1791c9565'::TEXT, ARRAY[605]::BIGINT[]),
    (497::BIGINT, 'Para verano y no aprender mucho es excelente!'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'f113d51a0c36587cfbfd08f39208805f7a3547f3f202d099543d099dd798071c'::TEXT, ARRAY[605, 923, 2444]::BIGINT[]),
    (497::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '4a95f8e13f445b32829e4f47ce645bdb3159d1c8d54ecd66c9ca2bd90db67ad5'::TEXT, ARRAY[563]::BIGINT[]),
    (497::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'd959b34cf8dcd71078ffc56965db5080abc0959f77200a7be5a9a639eec12d05'::TEXT, ARRAY[605]::BIGINT[]),
    (497::BIGINT, 'Tiene métodos muy extraños para enseñar, diferentes a los demás profes, pero sin más simples, entonces termina siendo más fácil desarrollar los problemas de examen...'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'ff13ecc11f234cd20a4fb34f6186b35e78821dc7521422a08e5809c2945475ed'::TEXT, ARRAY[605]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
